{
  "name": "haiku-compact",
  "version": "0.3.0",
  "description": "Squish your context with Haiku when the prompt cache goes cold, so your main model re-caches a short summary instead of the whole transcript. One line above the prompt shows up only when the cache is cold, says what a squish saves, then what it saved.",
  "author": {
    "name": "kjhq",
    "url": "https://github.com/kjhq"
  },
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "summaryModel": {
      "type": "string",
      "title": "Summary model",
      "description": "Model that writes the summary, and the word after /compact that selects it (alias or full id).",
      "default": "haiku"
    },
    "keepMessages": {
      "type": "number",
      "title": "Messages kept verbatim",
      "description": "How many recent messages to keep word for word after the summary.",
      "default": 4
    },
    "cacheTtlMinutes": {
      "type": "number",
      "title": "Prompt-cache TTL (minutes)",
      "description": "How long your prompt cache stays warm: 60 or 5. The band shows once it has passed.",
      "default": 60
    },
    "minTokens": {
      "type": "number",
      "title": "Minimum context tokens",
      "description": "Smaller contexts are left alone: no band, no compaction.",
      "default": 40000
    },
    "autoCompactOnResume": {
      "type": "boolean",
      "title": "Compact on a cold resume",
      "description": "Resuming a session whose cache has gone cold squishes it with the summary model at once.",
      "default": true
    },
    "holdPromptWhenCold": {
      "type": "boolean",
      "title": "Hold the first prompt when cold",
      "description": "Hold your first prompt after the cache went cold and offer /compact haiku first; sending it again skips that.",
      "default": true
    }
  }
}

